import { test, expect } from '@playwright/test';

test.describe('Debounced Search Functionality', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/search');
  });

  test('should trigger search only after user stops typing for 300ms', async ({ page }) => {
    // Setup: intercept the search API call
    await page.route('**/api/search', (route) => {
      route.continue();
    });

    // Verify search input exists
    const searchInput = page.getByPlaceholder('Search...');
    await expect(searchInput).toBeVisible();

    // Verify search results container exists
    const searchResults = page.getByRole('region', { name: /search results/i });
    await expect(searchResults).toBeVisible();

    // Verify initial state
    const resultsCount = page.getByText('0 results');
    await expect(resultsCount).toBeVisible();

    // Type quickly to trigger search
    await searchInput.fill('test');
    await page.waitForTimeout(100);

    // Verify search results are not displayed yet
    await expect(resultsCount).not.toBeVisible();

    // Type more characters to trigger search
    await searchInput.fill('test123');
    await page.waitForTimeout(100);

    // Verify search results are still not displayed
    await expect(resultsCount).not.toBeVisible();

    // Type pause for 300ms
    await page.waitForTimeout(300);

    // Verify search results container is now visible
    await expect(searchResults).toBeVisible();

    // Verify results count is displayed
    const resultsCountDisplay = page.getByText('1 result');
    await expect(resultsCountDisplay).toBeVisible();

    // Verify search results are displayed
    const resultItem = page.getByText('Test Result');
    await expect(resultItem).toBeVisible();

    // Verify search input is cleared
    await expect(searchInput).toHaveValue('');

    // Verify search debounce logic by typing again
    await searchInput.fill('test456');
    await page.waitForTimeout(100);

    // Verify search results are still visible
    await expect(searchResults).toBeVisible();

    // Verify search results count is updated
    const updatedResultsCount = page.getByText('1 result');
    await expect(updatedResultsCount).toBeVisible();

    // Verify search results are displayed
    const updatedResultItem = page.getByText('Test Result');
    await expect(updatedResultItem).toBeVisible();
  });

  test('should handle empty search input gracefully', async ({ page }) => {
    // Verify search input exists
    const searchInput = page.getByPlaceholder('Search...');
    await expect(searchInput).toBeVisible();

    // Verify search results container exists
    const searchResults = page.getByRole('region', { name: /search results/i });
    await expect(searchResults).toBeVisible();

    // Verify initial state
    const resultsCount = page.getByText('0 results');
    await expect(resultsCount).toBeVisible();

    // Verify no results are displayed for empty input
    const noResultsMessage = page.getByText('No results found');
    await expect(noResultsMessage).toBeVisible();

    // Verify search input is cleared when empty
    await expect(searchInput).toHaveValue('');

    // Verify no results are displayed after clearing
    await expect(searchResults).toBeVisible();

    // Verify no results message is still visible
    await expect(noResultsMessage).toBeVisible();
  });
});
